import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVat } from '../src/invoices.js';

test('createInvoice returns a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);

  assert.equal(r.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].qty, 5);
  assert.equal(r.value.lines[1].unitPrice, 8500);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice rejects an unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects an invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '07-10-2026',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects a date with no dashes', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '20261007',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects an invalid calendar date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects month 13', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects day 0', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-01-00',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects an empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects undefined lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: -1 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects an unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice with multiple lines rejects on the first invalid quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'DES-HOUR', qty: -1 },
      ],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice with multiple lines rejects on the first unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'UNKNOWN', qty: 1 },
      ],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal handles single quantity', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 6000 }), 6000);
});

test('lineTotal handles zero unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 0 }), 0);
});

test('invoiceTotals sums the line totals', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 95000 + 42500);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 }],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals with three lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 },
      { qty: 2, unitPrice: 120000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500 + 240000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 95000 + 42500 + 240000);
});

test('invoiceTotals with zero lines', () => {
  const invoice = {
    lines: [],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals on a created invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 10 * 9500 + 5 * 8500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 10 * 9500 * 0.21 + 5 * 8500 * 0.21);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('addLine adds a new line to an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 5 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].qty, 10);
  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 5);
  assert.equal(r2.value.lines[1].name, 'Design work (hour)');
  assert.equal(r2.value.lines[1].unitPrice, 8500);
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].qty, 15);
});

test('addLine preserves other line properties when increasing qty', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(r2.value.lines[0].name, 'Development (hour)');
  assert.equal(r2.value.lines[0].unitPrice, 9500);
  assert.equal(r2.value.lines[0].vatRate, 21);
});

test('addLine rejects invalid qty', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine rejects fractional qty', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine rejects unknown SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(addLine(r1.value, { sku: 'UNKNOWN', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const nonDraftInvoice = { ...r1.value, status: 'sent' };

  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'DES-HOUR', qty: 5 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r1.value));

  addLine(r1.value, { sku: 'DES-HOUR', qty: 5 });

  assert.deepEqual(r1.value, invoiceCopy);
});

test('removeLine removes a line from an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const r2 = removeLine(r1.value, 'DEV-HOUR');

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('removeLine returns LINE_NOT_FOUND if SKU is not on invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(removeLine(r1.value, 'UNKNOWN'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine returns NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(removeLine(r1.value, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const nonDraftInvoice = { ...r1.value, status: 'sent' };

  assert.deepEqual(removeLine(nonDraftInvoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r1.value));

  removeLine(r1.value, 'DES-HOUR');

  assert.deepEqual(r1.value, invoiceCopy);
});

test('removeLine works with three lines', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  const r2 = removeLine(r1.value, 'DES-HOUR');

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].sku, 'COPY-HOUR');
});

test('addLine and removeLine can be chained', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 5 });
  const r3 = addLine(r2.value, { sku: 'COPY-HOUR', qty: 2 });
  const r4 = removeLine(r3.value, 'DES-HOUR');

  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.equal(r4.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r4.value.lines[1].sku, 'COPY-HOUR');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = issueInvoice(r1.value, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
});

test('issueInvoice preserves invoice data', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const r2 = issueInvoice(r1.value, []);

  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].qty, 10);
  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 5);
});

test('issueInvoice uses existing numbers to avoid duplicates', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const existingNumbers = ['INV-2026-0001', 'INV-2026-0002'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice starts fresh for a new year', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const existingNumbers = ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.value.number, 'INV-2027-0001');
});

test('issueInvoice rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedInvoice = { ...r1.value, status: 'issued', number: 'INV-2026-0001' };

  assert.deepEqual(issueInvoice(issuedInvoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r1.value));

  issueInvoice(r1.value, []);

  assert.deepEqual(r1.value, invoiceCopy);
});

test('issueInvoice does not mutate line objects', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const originalLine = r1.value.lines[0];
  const originalLineCopy = JSON.parse(JSON.stringify(originalLine));

  const r2 = issueInvoice(r1.value, []);

  assert.deepEqual(originalLine, originalLineCopy);
  assert.notEqual(r2.value.lines[0], originalLine);
});

test('createInvoice stores discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 20);
});

test('createInvoice defaults discountPercent to tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice rejects invalid discountPercent below 0', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects invalid discountPercent above 100', () => {
