    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects non-number discountPercent', () => {
  assert.deepEqual(
