  assert.equal(lineVat(lineWith9), 9000);
});

test('lineVat with 0% rate', () => {
  assert.equal(lineVat({ qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 }), 0);
});

test('lineVat with discount applied', () => {
  assert.equal(lineVat({ qty: 10, unitPrice: 9500, discountPercent: 20, vatRate: 21 }), 15876);
});

test('lineVat defaults to 0% if vatRate undefined', () => {
  assert.equal(lineVat({ qty: 10, unitPrice: 9500, discountPercent: 0 }), 0);
});

test('lineVat with decimal VAT rate', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  assert(vat > 0);
});

test('invoiceTotals includes discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 20 },
